59	/* Per-point AI advice for the alarm page.
60	 *
61	 * The board asks the agent for advice when the alarm set changes and caches
62	 * the validated answer, so the page itself never does IO and never blocks.
63	 *
64	 * Whether a point shows AI text is decided by vg_ui_alarm_advice_get() alone:
65	 * the entry has to match the alarm episode, and the round state is not part
66	 * of that test.  A refresh that fails leaves the validated document in place,
67	 * so advice that is still correct for the alarm on screen stays on screen.
68	 *
69	 * These states only choose the heading the page shows when nothing matches:
70	 * VG_UI_ADV_IDLE       no round outstanding and nothing for this alarm set
71	 * VG_UI_ADV_PENDING    a round is queued or running
72	 * VG_UI_ADV_READY      loaded advice answers the alarm set on screen
73	 * VG_UI_ADV_ERROR      no round in flight and nothing to show for this set
74	 * VG_UI_ADV_NO_CRED    the agent has no LLM credentials, so no round can help
75	 *
76	 * ERROR and NO_CRED are both "nothing to show", and the page falls back to the
77	 * rule summary either way.  They stay apart because the reader's next step
78	 * differs: ERROR means wait for a retry, NO_CRED means the board needs
79	 * provisioning again.  Collapsing them sent the 2026-09-17 investigation
80	 * looking for a bug in the advice feature while the LLM credentials were
81	 * simply gone from the eMMC.
82	 */
83	typedef enum {
84	    VG_UI_ADV_IDLE = 0,
85	    VG_UI_ADV_PENDING,
86	    VG_UI_ADV_READY,
87	    VG_UI_ADV_ERROR,
88	    VG_UI_ADV_NO_CRED
89	} vg_ui_advice_state_t;
