357	void vg_agent_round_tick(void)
358	{
359	  pthread_mutex_lock(&g_lock);
360	  if (g_state == VG_AGENT_ROUND_QUEUED)
361	    {
362	      if (g_submitting) { pthread_mutex_unlock(&g_lock); return; }
363	      g_submitting = true;
364	      pthread_mutex_unlock(&g_lock);
365	      round_submit();
366	      pthread_mutex_lock(&g_lock);
367	      g_submitting = false;
368	      if (g_state == VG_AGENT_ROUND_QUEUED &&
369	          (int32_t)(vg_agent_round_now_ms() - g_started_ms) >=
370	          (int32_t)VG_AGENT_ROUND_QUEUE_TIMEOUT_MS)
371	        {
372	          g_state = VG_AGENT_ROUND_ERROR;
373	          g_finished_ms = vg_agent_round_now_ms();
374	          syslog(LOG_WARNING, "[%s] round never reached the agent\n", TAG);
375	        }
376	      pthread_mutex_unlock(&g_lock);
377	      return;
378	    }
379	  if (g_state != VG_AGENT_ROUND_RUNNING)
380	    { pthread_mutex_unlock(&g_lock); return; }
381	
382	  uint32_t now = vg_agent_round_now_ms();
383	  if (g_reply_seen)
384	    {
385	      bool ok = g_reply_ok;
386	      g_reply_seen = false;
387	      g_state = ok ? VG_AGENT_ROUND_DONE : VG_AGENT_ROUND_ERROR;
388	      if (ok) g_generation++;
389	      g_finished_ms = now;
390	      pthread_mutex_unlock(&g_lock);
391	      syslog(LOG_INFO, "[%s] round finished: %s\n", TAG, ok ? "reply" : "agent error");
392	      return;
393	    }
394	  if ((g_deadline_ms != 0 && (int32_t)(now - g_deadline_ms) >= 0) ||
395	      (int32_t)(now - g_started_ms) >= (int32_t)VG_AGENT_ROUND_TIMEOUT_MS)
396	    {
397	      g_state = VG_AGENT_ROUND_ERROR;
398	      g_finished_ms = now;
399	      velaclaw_client_abandon(g_client);
400	      pthread_mutex_unlock(&g_lock);
401	      syslog(LOG_WARNING, "[%s] round timed out\n", TAG);
402	      return;
403	    }
404	  pthread_mutex_unlock(&g_lock);
405	}
