444	bool vg_agent_round_reclaim(enum vg_agent_round_owner mine, uint32_t grace_ms)
445	{
446	  bool released = false;
447	
448	  pthread_mutex_lock(&g_lock);
449	
450	  if ((g_state == VG_AGENT_ROUND_DONE || g_state == VG_AGENT_ROUND_ERROR) &&
451	      g_owner != mine && g_finished_ms != 0 &&
452	      vg_agent_round_now_ms() - g_finished_ms >= grace_ms)
453	    {
454	      /* Somebody else's finished round that nobody is going to read - a
455	       * manual round killed half way, or a flow that went away.  Without
456	       * this the strict queue would hold the channel for it forever. */
457	
458	      if (g_owner == VG_AGENT_ROUND_OWNER_VOICE)
459	        {
460	          memset(g_req, 0, sizeof(g_req));
461	          memset(g_reply, 0, sizeof(g_reply));
462	        }
463	      g_state = VG_AGENT_ROUND_IDLE;
464	      g_owner = VG_AGENT_ROUND_OWNER_NONE;
465	      restore_background_locked();
466	      released = true;
467	    }
468	
469	  pthread_mutex_unlock(&g_lock);
470	  return released;
471	}
